<script>
  document.querySelectorAll('.v3-slider button').forEach((button, index) => button.addEventListener('click', () => { document.querySelectorAll('.v3-slider button, .v3-hero-images > div').forEach(element => element.classList.remove('active', 'is-active')); button.classList.add('active'); document.querySelectorAll('.v3-hero-images > div')[index].classList.add('is-active'); }));
  const heroButtons = document.querySelectorAll('.v3-slider button'); let heroSlide = 0; let heroTimer = setInterval(() => { heroSlide = (heroSlide + 1) % heroButtons.length; heroButtons[heroSlide].click(); }, 6500); heroButtons.forEach((button, index) => button.addEventListener('click', () => { heroSlide = index; }));
  const journeyCards = document.querySelectorAll('[data-journey-card]'); document.querySelectorAll('.v3-journey-tabs button').forEach((button, index) => button.addEventListener('click', () => { const section = document.querySelector('.v3-journey'); if (section.classList.contains('scroll-journey')) { window.scrollTo({top: section.offsetTop + (section.offsetHeight - innerHeight) * (index / 3), behavior: 'smooth'}); return; } document.querySelectorAll('.v3-journey-tabs button').forEach(element => element.classList.remove('active')); journeyCards.forEach(element => element.classList.remove('active')); button.classList.add('active'); journeyCards[index].classList.add('active'); }));
  const journey = document.querySelector('.v3-journey');
  if (journey && !matchMedia('(prefers-reduced-motion: reduce)').matches) {
    const sticky = document.createElement('div'), rail = document.createElement('div');
    sticky.className = 'v3-journey-sticky'; rail.className = 'v3-journey-rail';
    sticky.append(journey.querySelector('.v3-section-head'), journey.querySelector('.v3-journey-tabs'));
    journeyCards.forEach(card => { card.classList.add('active'); rail.append(card); });
    sticky.append(rail); journey.append(sticky); journey.classList.add('scroll-journey');
    const updateJourney = () => { const distance = journey.offsetHeight - innerHeight; const progress = Math.min(1, Math.max(0, -journey.getBoundingClientRect().top / Math.max(1, distance))); const travel = Math.max(0, rail.scrollWidth - innerWidth + 2 * parseFloat(getComputedStyle(sticky).paddingLeft)); rail.style.transform = `translateX(${-progress * travel}px)`; document.querySelectorAll('.v3-journey-tabs button').forEach((button, index) => { button.classList.toggle('active', Math.min(3, Math.floor(progress * 4)) === index); button.style.setProperty('--fill', `${Math.max(0, Math.min(1, progress * 4 - index)) * 100}%`); }); };
    addEventListener('scroll', updateJourney, {passive:true}); addEventListener('resize', updateJourney); updateJourney();
  }
  document.querySelectorAll('.v3-service-panel').forEach(panel => panel.addEventListener('mouseenter', () => { document.querySelectorAll('.v3-service-panel').forEach(element => element.classList.remove('active')); panel.classList.add('active'); }));
  const rail = document.querySelector('.v3-project-rail'); document.querySelectorAll('.v3-rail-controls button').forEach((button, index) => button.addEventListener('click', () => rail?.scrollBy({left: index ? 420 : -420, behavior: 'smooth'})));
</script>
